[
  {
    "pda_other_regret_expectation": "I think they'll regret it badly.",
    "sys_consequence_reasoning": "five people keep their lives."
  },
  {
    "sys_consequence_reasoning": "Five lives against an empty stretch of track",
    "pda_other_regret_expectation": "tended to replay it for a long, long time afterward."
  },
  {
    "sys_consequence_reasoning": "The lever just sends the train somewhere harmless.",
    "pda_other_regret_expectation": "One of them might later wish they'd kept a better lookout"
  },
  {
    "sys_consequence_reasoning": "doing nothing means five people probably get hit.",
    "pda_other_regret_expectation": "ever looking back and wishing they hadn't."
  },
  {
    "sys_consequence_reasoning": "choosing between nothing and five funerals.",
    "pda_other_regret_expectation": "would wish, for a very long time, that they'd checked one more time."
  },
  {
    "sys_consequence_reasoning": "Nobody's endangered by it",
    "pda_other_regret_expectation": "Someone who let this train go past would feel that far worse"
  },
  {
    "sys_consequence_reasoning": "Five workers, one empty siding, one lever.",
    "pda_other_regret_expectation": "I doubt they'd regret it."
  },
  {
    "sys_consequence_reasoning": "the alternative is five people struck by a train.",
    "pda_other_regret_expectation": "wishing they'd set it properly."
  },
  {
    "sys_consequence_reasoning": "since the siding is empty and the barrier stops it.",
    "pda_other_regret_expectation": "I think they'd wish they'd moved faster"
  },
  {
    "sys_consequence_reasoning": "Leaving the lever alone gives no benefit to anyone",
    "pda_other_regret_expectation": "one of them might wish they'd chosen a different spot"
  }
]
